/* Token Radar B — light paper theme. No network, no framework. */
:root {
  --paper: #faf6ee;
  --card: #fffdf8;
  --ink: #23201a;
  --muted: #6f6a5c;
  --line: #e3dcc9;
  --accent: #b4431f;
  --accent-soft: #fbe9df;
  --sage: #3f6b4f;
  --sage-soft: #e4efe6;
  --gold: #8a6d1b;
  --gold-soft: #f7eeda;
  --bar: #c98a2e;
}
* { box-sizing: border-box; }
body {
  margin: 0 auto;
  max-width: 1080px;
  padding: 28px 20px 48px;
  background: var(--paper);
  color: var(--ink);
  font: 15px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif;
}
h1 {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 34px;
  line-height: 1.15;
  margin: 6px 0 10px;
  letter-spacing: -0.01em;
}
.eyebrow {
  margin: 0;
  color: var(--accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.lede { max-width: 72ch; margin: 0 0 18px; font-size: 16px; }
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin: 0 0 20px;
}
.stats div {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 14px;
}
.stats dt { font-size: 12px; color: var(--muted); margin: 0; }
.stats dd { font-size: 22px; font-weight: 700; margin: 2px 0 0; font-family: Georgia, serif; }
.method {
  background: var(--card);
  border: 1px solid var(--line);
  border-left: 4px solid var(--accent);
  border-radius: 8px;
  padding: 12px 16px;
  margin-bottom: 18px;
}
.method summary { cursor: pointer; font-weight: 700; font-size: 16px; }
.method code { background: var(--accent-soft); padding: 1px 5px; border-radius: 4px; font-size: 13px; }
.method ul { margin: 10px 0; padding-left: 20px; }
.method li { margin-bottom: 6px; }
.mult-table { border-collapse: collapse; font-size: 13px; margin-top: 8px; }
.mult-table th, .mult-table td { border: 1px solid var(--line); padding: 4px 10px; text-align: left; }
.mult-table th { background: var(--gold-soft); }
.mult-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.catsum {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px 16px;
  margin-bottom: 18px;
}
.catsum h2 { font-family: Georgia, serif; font-size: 18px; margin: 0 0 2px; }
.catsum p { margin: 0 0 6px; font-size: 13px; color: var(--muted); }
.catsum .mult-table { width: 100%; }
.catsum tbody tr.cat-row { cursor: pointer; }
.catsum tbody tr.cat-row:hover { background: var(--accent-soft); }
.catsum tbody tr.cat-row.active { background: var(--sage-soft); }
.early-lead {
  background: var(--sage-soft);
  border: 1px solid var(--sage);
  border-left: 4px solid var(--sage);
  border-radius: 8px;
  padding: 10px 14px;
  margin: 0 0 12px;
  font-size: 14px;
}
.detail .compare { font-size: 13px; color: var(--muted); margin: 0 0 14px; }
#showMore {
  border: 1px solid var(--accent);
  background: var(--card);
  color: var(--accent);
  border-radius: 6px;
  padding: 6px 18px;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
}
#showMore:hover { background: var(--accent-soft); }
.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  align-items: end;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 6px;
}
.controls label { font-size: 13px; color: var(--muted); display: flex; flex-direction: column; gap: 3px; }
.controls label.check { flex-direction: row; align-items: center; gap: 6px; padding-bottom: 6px; color: var(--ink); }
.controls input[type="search"], .controls select {
  font: inherit;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 6px 8px;
  min-width: 150px;
}
.count { color: var(--muted); font-size: 13px; margin: 10px 0; }
.detail {
  background: var(--card);
  border: 1px solid var(--line);
  border-top: 4px solid var(--sage);
  border-radius: 8px;
  padding: 18px 20px;
  margin: 6px 0 18px;
}
.detail h2 { font-family: Georgia, serif; font-size: 24px; margin: 0 0 2px; }
.detail .sub { color: var(--muted); margin: 0 0 12px; }
.detail .why { font-size: 16px; margin: 0 0 14px; }
.detail .warn {
  background: var(--accent-soft);
  border: 1px solid var(--accent);
  border-left: 4px solid var(--accent);
  border-radius: 8px;
  padding: 10px 14px;
  margin: 0 0 14px;
  font-size: 14px;
}
.factors { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; margin: 0 0 14px; }
.factor { border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; }
.factor b { display: block; font-size: 18px; font-family: Georgia, serif; }
.factor span { font-size: 12px; color: var(--muted); }
.factor .track { height: 6px; background: var(--line); border-radius: 3px; margin-top: 6px; }
.factor .fill { height: 6px; background: var(--bar); border-radius: 3px; }
.flags { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 12px; padding: 0; list-style: none; }
.flags li {
  background: var(--gold-soft);
  color: var(--gold);
  border-radius: 20px;
  padding: 3px 10px;
  font-size: 12px;
  font-weight: 600;
}
.detail h3 { margin: 14px 0 6px; font-size: 15px; }
.steps { margin: 0; padding-left: 20px; }
.steps li { margin-bottom: 8px; }
.steps .tag {
  display: inline-block;
  background: var(--sage-soft);
  color: var(--sage);
  border-radius: 4px;
  padding: 0 6px;
  margin-right: 6px;
  font-size: 12px;
  font-weight: 700;
}
.detail .close { float: right; border: 1px solid var(--line); background: var(--paper); border-radius: 6px; padding: 4px 10px; cursor: pointer; font: inherit; }
.board { width: 100%; border-collapse: collapse; background: var(--card); border: 1px solid var(--line); }
/* The 9-column board (and the summary tables) are wider than a phone:
   let the table scroll inside its own box instead of pushing the page
   wider than the viewport (mobile check, v4). */
.board-wrap, .table-wrap { overflow-x: auto; }
.board th, .board td { padding: 8px 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: middle; }
.board thead th { background: var(--gold-soft); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover { background: var(--accent-soft); }
.board tbody tr.selected { background: var(--sage-soft); }
.board .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.board .name { font-weight: 700; }
.badge {
  display: inline-block;
  background: var(--sage);
  color: #fff;
  border-radius: 4px;
  padding: 1px 6px;
  margin-left: 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  vertical-align: 2px;
}
.bar { display: inline-block; height: 8px; background: var(--bar); border-radius: 4px; vertical-align: middle; }
.more { color: var(--muted); font-size: 13px; text-align: center; }
footer { margin-top: 26px; color: var(--muted); font-size: 13px; border-top: 1px solid var(--line); padding-top: 14px; }
footer code { background: var(--accent-soft); padding: 0 4px; border-radius: 4px; }
@media (max-width: 720px) {
  .stats { grid-template-columns: repeat(2, 1fr); }
  .factors { grid-template-columns: repeat(2, 1fr); }
  h1 { font-size: 26px; }
}
